macro_rules! inflateGetDictionary {
    () => {
        # [doc = " Returns the sliding dictionary being maintained by inflate.  "] # [doc = ""] # [doc = " `dictLength` is set to the number of bytes in the dictionary, and that many bytes are copied"] # [doc = " to `dictionary`. `dictionary` must have enough space, where `32768` bytes is"] # [doc = " always enough.  If [`inflateGetDictionary`] is called with `dictionary` equal to"] # [doc = " `NULL`, then only the dictionary length is returned, and nothing is copied."] # [doc = " Similarly, if `dictLength` is `NULL`, then it is not set."] # [doc = ""] # [doc = " # Returns"] # [doc = ""] # [doc = " * [`Z_OK`] if success"] # [doc = " * [`Z_STREAM_ERROR`] if the stream state is inconsistent"] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " - `dictionary` must `NULL` or writable for the dictionary length (`32768` is always enough)"] # [doc = " - `dictLength` must `NULL` or satisfy the requirements of [`pointer::as_mut`]"] # [doc = ""] # [doc = " [`pointer::as_mut`]: https://doc.rust-lang.org/core/primitive.pointer.html#method.as_mut"] # [cfg_attr (feature = "export-symbols" , export_name = prefix ! (inflateGetDictionary))] pub unsafe extern "C-unwind" fn inflateGetDictionary (strm : * const z_stream , dictionary : * mut c_uchar , dictLength : * mut c_uint ,) -> c_int { let Some (stream) = InflateStream :: from_stream_ref (strm) else { return ReturnCode :: StreamError as c_int ; } ; let whave = zlib_rs :: inflate :: get_dictionary (stream , dictionary) ; if let Some (dictLength) = unsafe { dictLength . as_mut () } { * dictLength = whave as c_uint ; } ReturnCode :: Ok as _ }
    };
}

inflateGetDictionary!();